import itertools

def is_harmonious(n, m):
    # Generate all non-empty subsets of {0, ..., n-1}
    subsets = []
    for i in range(1, 2**n):
        s = set()
        for j in range(n):
            if (i >> j) & 1:
                s.add(j)
        subsets.append(s)

    # Try all possible ways to pick 2m distinct subsets
    # This is too many. Let's try to pick X and Y separately.
    # But the number of subsets is small (2^n - 1).

    from itertools import combinations

    # Instead of all combinations, let's use a more heuristic approach or 
    # smaller search space.
    # For a fixed X, we can find all Y's that are cross-intersecting with X.

    for X_indices in combinations(range(len(subsets)), m):
        X = [subsets[i] for i in X_indices]
        # Find all subsets that intersect every set in X
        Y_candidates = []
        for i in range(len(subsets)):
            s = subsets[i]
            if all(s & x for x in X):
                Y_candidates.append(s)

        # We need at least m subsets in Y_candidates that are not in X
        # Filter out those already in X
        Y_available = [s for s in Y_candidates if s not in X]
        if len(Y_available) >= m:
            return True
    return False

