def is_harmonious(n, m):
    subsets = []
    for i in range(1, 2**n):
        s = set()
        for j in range(n):
            if (i >> j) & 1:
                s.add(j)
        subsets.append(s)

    from itertools import combinations

    # To speed up, we can iterate over X combinations more efficiently
    # or use a different strategy.
    # Let's just try a few X's? No, let's try all X's for small n.

    for X_indices in combinations(range(len(subsets)), m):
        X = [subsets[i] for i in X_indices]
        Y_available = []
        for s in subsets:
            if all(s & x for x in X):
                # Check if s is not in X
                # This is a bit slow.
                is_in_X = False
                for x in X:
                    if s == x:
                        is_in_X = True
                        break
                if not is_in_X:
                    Y_available.append(s)
        if len(Y_available) >= m:
            return True
    return False

